Implement a basic DLL injection in C:

```c
#include <windows.h>
#include <stdio.h>

int main(int argc, char* argv[]) {
    if (argc < 3) {
        printf("Usage: injector.exe <PID> <DLL_PATH>\n");
        return 1;
    }

    DWORD pid = atoi(argv[1]);
    char* dllPath = argv[2];

    // Step 1: Open target process
    HANDLE hProcess = OpenProcess(
        PROCESS_CREATE_THREAD | PROCESS_VM_OPERATION | 
        PROCESS_VM_WRITE, FALSE, pid);
    if (!hProcess) { printf("OpenProcess failed\n"); return 1; }

    // Step 2: Allocate memory in target
    SIZE_T pathLen = strlen(dllPath) + 1;
    LPVOID remoteBuf = VirtualAllocEx(hProcess, NULL, pathLen,
        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!remoteBuf) { printf("VirtualAllocEx failed\n"); return 1; }

    // Step 3: Write DLL path to target
    if (!WriteProcessMemory(hProcess, remoteBuf, dllPath, 
        pathLen, NULL)) { printf("WriteProcessMemory failed\n"); return 1; }

    // Step 4: Create remote thread to call LoadLibrary
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0,
        (LPTHREAD_START_ROUTINE)LoadLibraryA, remoteBuf, 0, NULL);
    if (!hThread) { printf("CreateRemoteThread failed\n"); return 1; }

    WaitForSingleObject(hThread, INFINITE);
    printf("DLL injected successfully!\n");

    VirtualFreeEx(hProcess, remoteBuf, 0, MEM_RELEASE);
    CloseHandle(hThread);
    CloseHandle(hProcess);
    return 0;
}
```

